fn render(input: &str) -> String {
    let url = Url::new(input.as_bytes());
    let flag = |b: bool| if b { "1" } else { "0" }.to_string();
    let text = |b: &[u8]| String::from_utf8_lossy(b).into_owned();
    let fields = vec![
        text(url.scheme()),
        text(url.authority()),
        text(url.userinfo()),
        text(url.host()),
        url.port().to_string(),
        text(url.path()),
        text(url.query()),
        text(url.fragment()),
        flag(url.has_scheme()),
        flag(url.has_authority()),
        flag(url.has_userinfo()),
        flag(url.has_host()),
        flag(url.has_port()),
        flag(url.has_path()),
        flag(url.has_query()),
        flag(url.has_fragment()),
        text(url.to_string()),
        flag(url.is_valid()),
    ];
    fields.join("|")
}

