const CASES: &[(&str, &str)] = &[
    // The five examples documented in test18.cpp.
    (
        "http://www.example.com",
        "http|www.example.com||www.example.com|-1|||1|1|0|1|0|0|0|0|http://www.example.com|1",
    ),
    (
        "https://www.example.com",
        "https|www.example.com||www.example.com|-1|||1|1|0|1|0|0|0|0|https://www.example.com|1",
    ),
    (
        "ftp://ftp.example.com/files",
        "ftp|ftp.example.com||ftp.example.com|-1|/files|||1|1|0|1|0|1|0|0|ftp://ftp.example.com/files|1",
    ),
    (
        "http://user:pass@example.com",
        "http|user:pass@example.com|user:pass|example.com|-1|||1|1|1|1|0|0|0|0|http://user:pass@example.com|1",
    ),
    (
        "http://example.com:8080",
        "http|example.com:8080||example.com|8080|||1|1|0|1|1|0|0|0|http://example.com:8080|1",
    ),
