fn non_ascii_bytes_pass_through_untouched() {
    let url = Url::new("http://exämple.com/pä?q=ä#ä".as_bytes());
    assert_eq!(url.host(), "exämple.com".as_bytes());
    assert_eq!(url.path(), "/pä".as_bytes());
    assert_eq!(url.query(), "q=ä".as_bytes());
    assert_eq!(url.fragment(), "ä".as_bytes());
    assert_eq!(url.to_string(), "http://exämple.com/pä?q=ä#ä".as_bytes());

