//! Port of `tests/test18.cpp`: parse `argv[1]` and dump every accessor.
//!
//! The eighteen lines below are written in the same order as the C++ test and
//! with the same formatting `std::cout` would use — booleans as `1`/`0`, the
//! port as a plain integer. Components are written as raw bytes so a URL
//! carrying non-ASCII survives byte for byte.

#[path = "src/url_parser/mod.rs"]
mod url_parser;

use std::io::{self, BufWriter, Write};
use url_parser::Url;

fn write_line<W: Write>(out: &mut W, value: &[u8]) -> io::Result<()> {
    out.write_all(value)?;
    out.write_all(b"\n")
}

fn write_bool<W: Write>(out: &mut W, value: bool) -> io::Result<()> {
    write_line(out, if value { b"1" } else { b"0" })
}

fn run(out: &mut impl Write, url: &str) -> io::Result<()> {
    let parser = Url::new(url.as_bytes());

    // Test all getters
    write_line(out, parser.scheme())?;
    write_line(out, parser.authority())?;
    write_line(out, parser.userinfo())?;
    write_line(out, parser.host())?;
    write_line(out, parser.port().to_string().as_bytes())?;
    write_line(out, parser.path())?;
    write_line(out, parser.query())?;
    write_line(out, parser.fragment())?;

    // Test all has_* methods
    write_bool(out, parser.has_scheme())?;
    write_bool(out, parser.has_authority())?;
    write_bool(out, parser.has_userinfo())?;
    write_bool(out, parser.has_host())?;
    write_bool(out, parser.has_port())?;
    write_bool(out, parser.has_path())?;
    write_bool(out, parser.has_query())?;
    write_bool(out, parser.has_fragment())?;

    // Test to_string and is_valid
    write_line(out, parser.to_string())?;
    write_bool(out, parser.is_valid())?;

    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let url = &args[1];
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    if run(&mut out, url).and_then(|()| out.flush()).is_err() {
        std::process::exit(1);
    }
}

